-- Sorts du Manuel des joueurs absents du DRS : niveaux 0 à 9, résumés en français avec nos propres mots.
-- Généré depuis supabase/seed/phb_spells.json : ne pas modifier à la main.
-- Sans danger si on le relance : un sort déjà présent (même nom) n'est pas ajouté deux fois.

insert into public.spells (name, level, school, classes, casting_time, range, components, duration, concentration, ritual, description)
select v.name, v.level, v.school, v.classes::text[], v.casting_time, v.range, v.components, v.duration, v.concentration, v.ritual, v.description
from (values
  ('Amis', 0, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Personnelle', 'S, M', 'Jusqu''à 1 minute', true, false, 'Tu as l''avantage aux tests de Charisme contre une créature non hostile. À la fin du sort, elle comprend qu''elle a été influencée et peut devenir hostile.'),
  ('Fouet épineux', 0, 'Transmutation', '{"Druide"}', '1 action', '9 m', 'V, S, M', 'Instantanée', false, false, 'Attaque de sort au corps à corps (allonge 9 m) : 1d6 dégâts perforants et tu tires une cible de taille Grande ou moins de 3 m vers toi. Dégâts accrus aux niveaux 5, 11 et 17.'),
  ('Protection contre les armes', 0, 'Abjuration', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Personnelle', 'V, S', '1 round', false, false, 'Jusqu''à la fin de ton prochain tour, tu as la résistance aux dégâts contondants, perforants et tranchants infligés par des attaques avec une arme.'),
  ('Armure d''Agathys', 1, 'Abjuration', '{"Occultiste"}', '1 action', 'Personnelle', 'V, S, M', '1 heure', false, false, 'Tu gagnes 5 PV temporaires. Tant qu''ils durent, une créature qui te touche au corps à corps subit 5 dégâts de froid. +5 PV et +5 dégâts par niveau d''emplacement au-delà du 1er.'),
  ('Carreau ensorcelé', 1, 'Évocation', '{"Ensorceleur","Magicien","Occultiste"}', '1 action', '9 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Attaque de sort à distance : 1d12 dégâts de foudre. Les tours suivants, ton action maintient l''arc pour 1d12 automatiques tant que la cible reste à portée. +1d12 initial par niveau au-delà du 1er.'),
  ('Disque flottant de Tenser', 1, 'Invocation', '{"Magicien"}', '1 action', '9 m', 'V, S, M', '1 heure', false, true, 'Un disque de force d''environ 1 m flotte à 1 m du sol et porte jusqu''à 250 kg. Il te suit à 6 m de distance et disparaît si tu t''éloignes de plus de 30 m.'),
  ('Duel forcé', 1, 'Enchantement', '{"Paladin"}', '1 action bonus', '9 m', 'V', 'Jusqu''à 1 minute', true, false, 'Jet de Sagesse : en cas d''échec, la cible a le désavantage pour attaquer d''autres créatures que toi et doit réussir un nouveau jet pour s''éloigner à plus de 9 m de toi.'),
  ('Frappe ardente', 1, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche ajoute 1d6 dégâts de feu et enflamme la cible : 1d6 de feu au début de chacun de ses tours jusqu''à un jet de Constitution réussi. +1d6 initial par niveau au-delà du 1er.'),
  ('Frappe colérique', 1, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée au corps à corps qui touche inflige 1d6 dégâts psychiques de plus. Jet de Sagesse ou la cible est effrayée ; elle peut retenter avec un test de Sagesse en action.'),
  ('Frappe piégeuse', 1, 'Invocation', '{"Rôdeur"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche fait surgir des ronces : jet de Force ou la cible est entravée et subit 1d6 dégâts perforants à chacun de ses tours (avantage si Grande ou plus). +1d6 par niveau au-delà du 1er.'),
  ('Frappe tonitruante', 1, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée au corps à corps qui touche ajoute 2d6 dégâts de tonnerre. Jet de Force ou la cible est repoussée de 3 m et jetée à terre.'),
  ('Grêle d''épines', 1, 'Invocation', '{"Rôdeur"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque à distance qui touche fait éclater une pluie d''épines : la cible et chaque créature à 1,50 m font un jet de Dextérité, 1d10 dégâts perforants (moitié si réussi). +1d10 par niveau au-delà du 1er (max 6d10).'),
  ('Maléfice', 1, 'Enchantement', '{"Occultiste"}', '1 action bonus', '27 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Tes attaques qui touchent la cible maudite infligent 1d6 dégâts nécrotiques de plus, et elle a le désavantage aux tests d''une caractéristique choisie. Transférable par action bonus si elle tombe à 0 PV. Durée allongée aux niveaux supérieurs.'),
  ('Murmures dissonants', 1, 'Enchantement', '{"Barde"}', '1 action', '18 m', 'V', 'Instantanée', false, false, 'Jet de Sagesse : 3d6 dégâts psychiques et la cible doit fuir immédiatement avec sa réaction (moitié et pas de fuite si réussi). +1d6 par niveau au-delà du 1er.'),
  ('Orbe chromatique', 1, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', '27 m', 'V, S, M', 'Instantanée', false, false, 'Attaque de sort à distance : 3d8 dégâts d''acide, de froid, de feu, de foudre, de poison ou de tonnerre, au choix. +1d8 par niveau au-delà du 1er.'),
  ('Rayon empoisonné', 1, 'Nécromancie', '{"Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'Attaque de sort à distance : 2d8 dégâts de poison, puis jet de Constitution ou la cible est empoisonnée jusqu''à la fin de ton prochain tour. +1d8 par niveau au-delà du 1er.'),
  ('Tentacules d''Hadar', 1, 'Invocation', '{"Occultiste"}', '1 action', 'Personnelle (rayon de 3 m)', 'V, S', 'Instantanée', false, false, 'Chaque créature à 3 m de toi fait un jet de Force : 2d6 dégâts nécrotiques et plus de réaction ce tour (moitié seulement si réussi). +1d6 par niveau au-delà du 1er.'),
  ('Cordon de flèches', 2, 'Transmutation', '{"Rôdeur"}', '1 action', '1,50 m', 'V, S, M', '8 heures', false, false, 'Tu plantes quatre flèches ou carreaux qui tirent sur toute créature non exemptée arrivant à 9 m : attaque à distance, 1d6 dégâts perforants. +2 projectiles par niveau au-delà du 2e.'),
  ('Couronne du dément', 2, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '36 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Jet de Sagesse ou un humanoïde est charmé : à chacun de ses tours, il attaque au corps à corps une créature que tu désignes. Tu dois utiliser ton action pour maintenir le sort ; nouveau jet à chaque fin de tour.'),
  ('Force fantasmagorique', 2, 'Illusion', '{"Barde","Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Jet d''Intelligence ou la cible perçoit une illusion de la taille d''un cube de 3 m qu''elle croit réelle. Elle peut lui infliger 1d6 dégâts psychiques par tour. Une action d''examen (Investigation) permet de la percer.'),
  ('Frappe lumineuse', 2, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche ajoute 2d6 dégâts radiants ; la cible émet de la lumière faible et ne peut plus être invisible. +1d6 par niveau au-delà du 2e.'),
  ('Nuée de dagues', 2, 'Invocation', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Un cube de 1,50 m rempli de dagues tournoyantes inflige 4d4 dégâts tranchants à toute créature qui y entre ou y commence son tour. +2d4 par niveau au-delà du 2e.'),
  ('Sens animal', 2, 'Divination', '{"Druide","Rôdeur"}', '1 action', 'Contact', 'S', 'Jusqu''à 1 heure', true, true, 'Tu touches une bête consentante et peux, par une action, voir et entendre à travers ses sens ; tu es alors aveugle et sourd pour ton propre corps.'),
  ('Appétit d''Hadar', 3, 'Invocation', '{"Occultiste"}', '1 action', '45 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une sphère de 6 m de ténèbres magiques et de terrain difficile. Les créatures qui y commencent leur tour subissent 2d6 dégâts de froid, et 2d6 d''acide en fin de tour sur un jet de Dextérité raté. +1d6 de froid par niveau au-delà du 3e.'),
  ('Arme élémentaire', 3, 'Transmutation', '{"Paladin"}', '1 action', 'Contact', 'V, S', 'Jusqu''à 1 heure', true, false, 'Une arme non magique devient une arme +1 et inflige 1d4 dégâts supplémentaires d''acide, froid, feu, foudre ou tonnerre. Bonus et dés augmentent aux niveaux 5 et 7.'),
  ('Aura de vitalité', 3, 'Évocation', '{"Paladin"}', '1 action', 'Personnelle (rayon de 9 m)', 'V', 'Jusqu''à 1 minute', true, false, 'Aura de 9 m de rayon : à chaque tour, par une action bonus, tu rends 2d6 PV à une créature de l''aura, toi compris.'),
  ('Aura du croisé', 3, 'Évocation', '{"Paladin"}', '1 action', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Aura de 9 m de rayon : les attaques armées des créatures non hostiles qui s''y trouvent infligent 1d4 dégâts radiants supplémentaires.'),
  ('Croissance végétale', 3, 'Transmutation', '{"Barde","Druide","Rôdeur"}', '1 action ou 8 heures', '45 m', 'V, S', 'Instantanée', false, false, 'En une action, la végétation d''un rayon de 30 m devient si dense que se déplacer coûte 4 fois plus. En 8 heures, les cultures d''un rayon de 800 m sont enrichies et donnent double récolte pendant un an.'),
  ('Esprits gardiens', 3, 'Invocation', '{"Clerc"}', '1 action', 'Personnelle (rayon de 4,50 m)', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Des esprits t''entourent : la zone devient terrain difficile pour tes ennemis et chacun qui y entre ou y commence son tour fait un jet de Sagesse, 3d8 dégâts radiants ou nécrotiques (moitié si réussi). +1d8 par niveau au-delà du 3e.'),
  ('Feindre la mort', 3, 'Nécromancie', '{"Barde","Clerc","Druide","Magicien"}', '1 action', 'Contact', 'V, S, M', '1 heure', false, true, 'Une créature consentante semble morte : elle est aveuglée et neutralisée, sa vitesse tombe à 0 et elle résiste à tous les dégâts sauf psychiques. Elle est immunisée à l''empoisonnement.'),
  ('Flèche de foudre', 3, 'Transmutation', '{"Rôdeur"}', '1 action bonus', 'Personnelle', 'V, S', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque à distance devient un éclair : 4d8 dégâts de foudre (moitié si raté), puis chaque créature à 3 m de la cible fait un jet de Dextérité, 2d8 dégâts (moitié si réussi). +1d8 aux deux par niveau au-delà du 3e.'),
  ('Frappe aveuglante', 3, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche ajoute 3d8 dégâts radiants. Jet de Constitution ou la cible est aveuglée ; elle retente le jet à la fin de chacun de ses tours.'),
  ('Invoquer un tir de barrage', 3, 'Invocation', '{"Rôdeur"}', '1 action', 'Personnelle (cône de 18 m)', 'V, S, M', 'Instantanée', false, false, 'Tu démultiplies une munition ou arme de jet : chaque créature du cône fait un jet de Dextérité, 3d8 dégâts du type de l''arme (moitié si réussi). La munition est consommée.'),
  ('Monture fantôme', 3, 'Illusion', '{"Magicien"}', '1 minute', '9 m', 'V, S', '1 heure', false, true, 'Crée un cheval de taille Grande, quasi réel, avec selle et harnais, que toi ou une créature désignée pouvez monter. Il a une vitesse de 30 m et disparaît s''il subit des dégâts.'),
  ('Assassin imaginaire', 4, 'Illusion', '{"Magicien"}', '1 action', '36 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Jet de Sagesse ou la cible est effrayée par une illusion de ses pires peurs. À la fin de chacun de ses tours, nouveau jet : en cas d''échec, 4d10 dégâts psychiques ; une réussite met fin au sort. +1d10 par niveau au-delà du 4e.'),
  ('Aura de pureté', 4, 'Abjuration', '{"Paladin"}', '1 action', 'Personnelle (rayon de 9 m)', 'V', 'Jusqu''à 10 minutes', true, false, 'Aura de 9 m : les créatures non hostiles ne peuvent pas tomber malades, résistent aux dégâts de poison et ont l''avantage aux sauvegardes contre la plupart des états (aveuglé, charmé, effrayé, paralysé, empoisonné, etc.).'),
  ('Aura de vie', 4, 'Abjuration', '{"Paladin"}', '1 action', 'Personnelle (rayon de 9 m)', 'V', 'Jusqu''à 10 minutes', true, false, 'Aura de 9 m : les créatures non hostiles résistent aux dégâts nécrotiques et leur maximum de PV ne peut être réduit. Une créature alliée à 0 PV qui commence son tour dans l''aura récupère 1 PV.'),
  ('Bannissement', 4, 'Abjuration', '{"Clerc","Ensorceleur","Magicien","Occultiste","Paladin"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Jet de Charisme ou la cible est envoyée sur un demi-plan inoffensif (ou son plan d''origine si elle est extraplanaire et que le sort dure 1 minute complète). +1 cible par niveau au-delà du 4e.'),
  ('Bouclier de feu', 4, 'Évocation', '{"Magicien"}', '1 action', 'Personnelle', 'V, S, M', '10 minutes', false, false, 'Des flammes t''entourent et éclairent. Bouclier chaud : résistance au froid ; bouclier froid : résistance au feu. Qui te touche au corps à corps subit 2d8 dégâts de feu ou de froid selon le bouclier.'),
  ('Chien de garde de Mordenkainen', 4, 'Invocation', '{"Magicien"}', '1 action', '9 m', 'V, S, M', '8 heures', false, false, 'Un chien fantomatique invisible garde un point, aboie quand un intrus approche à 9 m et mord une créature hostile à 1,50 m : attaque avec ton bonus, 4d8 dégâts perforants.'),
  ('Coffre secret de Léomund', 4, 'Invocation', '{"Magicien"}', '1 action', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Tu caches un coffre précieux (et son contenu) dans le plan éthéré ; tu peux le rappeler par une action grâce à sa réplique miniature. Après 60 jours, l''effet peut prendre fin.'),
  ('Compulsion', 4, 'Enchantement', '{"Barde"}', '1 action', '9 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Les créatures choisies qui t''entendent font un jet de Sagesse. En cas d''échec, tu peux, par une action bonus, imposer une direction à leurs déplacements ; elles retentent le jet après chaque mouvement.'),
  ('Confusion', 4, 'Enchantement', '{"Barde","Druide","Ensorceleur","Magicien"}', '1 action', '27 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Chaque créature dans une sphère de 3 m fait un jet de Sagesse ; en cas d''échec, un d10 détermine son comportement à chaque tour (errance, inaction, attaque aléatoire…). +1,50 m de rayon par niveau au-delà du 4e.'),
  ('Contrôle de l''eau', 4, 'Transmutation', '{"Clerc","Druide","Magicien"}', '1 action', '90 m', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Tu contrôles l''eau dans un cube de 30 m : inondation, séparation des eaux, redirection d''un courant ou tourbillon (jet de Force, 2d8 dégâts contondants).'),
  ('Divination', 4, 'Divination', '{"Clerc"}', '1 action', 'Personnelle', 'V, S, M', 'Instantanée', false, true, 'Tu poses une question à ta divinité sur un événement des 7 prochains jours et reçois une réponse véridique, parfois cryptique. Les lancers répétés le même jour peuvent donner une réponse aléatoire.'),
  ('Dominer une bête', 4, 'Enchantement', '{"Druide","Ensorceleur"}', '1 action', '18 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Jet de Sagesse ou la bête est charmée et t''obéit par lien télépathique ; tu peux contrôler précisément ses actions. Nouveau jet à chaque dégât subi. Durée accrue aux niveaux supérieurs.'),
  ('Fabrication', 4, 'Transmutation', '{"Magicien"}', '10 minutes', '36 m', 'V, S', 'Instantanée', false, false, 'Transforme des matériaux bruts en un produit fini de même matière (pont, corde, vêtements…), jusqu''à un cube de 3 m (1,50 m pour les minéraux). Les objets de qualité demandent la maîtrise des outils adaptés.'),
  ('Façonnage de la pierre', 4, 'Transmutation', '{"Clerc","Druide","Magicien"}', '1 action', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Tu modèles un bloc de pierre de 1,50 m de côté maximum pour lui donner la forme voulue : arme, passage, porte grossière, statue…'),
  ('Flétrissement', 4, 'Nécromancie', '{"Druide","Ensorceleur","Magicien","Occultiste"}', '1 action', '9 m', 'V, S', 'Instantanée', false, false, 'Jet de Constitution : 8d8 dégâts nécrotiques (moitié si réussi). Sans effet sur les morts-vivants et artificiels ; les plantes ont le désavantage et subissent le maximum. +1d8 par niveau au-delà du 4e.'),
  ('Frappe assommante', 4, 'Évocation', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche ajoute 4d6 dégâts psychiques. Jet de Sagesse ou la cible a le désavantage à ses attaques et tests et ne peut pas réagir jusqu''à la fin de son prochain tour.'),
  ('Gardien de la foi', 4, 'Invocation', '{"Clerc"}', '1 action', '9 m', 'V', '8 heures', false, false, 'Un gardien spectral occupe un emplacement. Tout ennemi qui arrive à 3 m de lui fait un jet de Dextérité : 20 dégâts radiants (moitié si réussi). Il disparaît après avoir infligé 60 dégâts.'),
  ('Insecte géant', 4, 'Transmutation', '{"Druide"}', '1 action', '9 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Transforme jusqu''à dix mille-pattes, trois araignées, cinq guêpes ou un scorpion en versions géantes qui obéissent à tes ordres verbaux.'),
  ('Invisibilité supérieure', 4, 'Illusion', '{"Barde","Ensorceleur","Magicien"}', '1 action', 'Contact', 'V, S', 'Jusqu''à 1 minute', true, false, 'La créature touchée devient invisible pour la durée du sort, même si elle attaque ou lance des sorts.'),
  ('Invoquer des élémentaires mineurs', 4, 'Invocation', '{"Druide","Magicien"}', '1 minute', '27 m', 'V, S', 'Jusqu''à 1 heure', true, false, 'Tu invoques des élémentaires amicaux : un de FP 2, deux de FP 1, quatre de FP 1/2 ou huit de FP 1/4. Ils obéissent à tes ordres. Plus de créatures avec un emplacement de niveau 6 ou 8.'),
  ('Invoquer des êtres des bois', 4, 'Invocation', '{"Druide","Rôdeur"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Tu invoques des créatures féeriques amicales : une de FP 2, deux de FP 1, quatre de FP 1/2 ou huit de FP 1/4. Elles obéissent à tes ordres. Plus de créatures avec un emplacement de niveau 6 ou 8.'),
  ('Liane agrippeuse', 4, 'Invocation', '{"Druide","Rôdeur"}', '1 action bonus', '9 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Une liane surgit à portée. Par une action bonus, tu la fais saisir une créature à 9 m d''elle : jet de Dextérité ou la cible est tirée de 6 m vers la liane.'),
  ('Liberté de mouvement', 4, 'Abjuration', '{"Barde","Clerc","Druide","Rôdeur"}', '1 action', 'Contact', 'V, S, M', '1 heure', false, false, 'La créature touchée ignore le terrain difficile, ne peut être ralentie, paralysée ou entravée par la magie, et peut s''échapper d''une entrave avec 1,50 m de mouvement. Elle se déplace normalement sous l''eau.'),
  ('Localiser une créature', 4, 'Divination', '{"Barde","Clerc","Druide","Magicien","Paladin","Rôdeur"}', '1 action', 'Personnelle', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Tu sens la direction d''une créature connue ou d''un type de créature, si elle est à moins de 300 m. L''eau courante bloque le sort.'),
  ('Mur de feu', 4, 'Évocation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Un mur de feu (18 m de long, ou anneau de 6 m de diamètre). À l''apparition, jet de Dextérité : 5d8 dégâts de feu (moitié si réussi). Un côté brûle aussi ceux qui s''approchent à 3 m ou le traversent. +1d8 par niveau au-delà du 4e.'),
  ('Métamorphose', 4, 'Transmutation', '{"Barde","Druide","Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Jet de Sagesse (si non consentante) ou la créature devient une bête de FP inférieur ou égal au sien. Elle prend les PV de cette forme et reprend sa forme normale quand ils tombent à 0.'),
  ('Peau de pierre', 4, 'Abjuration', '{"Druide","Ensorceleur","Magicien","Rôdeur"}', '1 action', 'Contact', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Une créature consentante gagne la résistance aux dégâts contondants, perforants et tranchants non magiques.'),
  ('Porte dimensionnelle', 4, 'Invocation', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '150 m', 'V', 'Instantanée', false, false, 'Tu te téléportes à un endroit visible ou décrit à portée, avec un passager consentant éventuel. Si la destination est occupée, vous subissez 4d6 dégâts de force et le sort échoue.'),
  ('Protection contre la mort', 4, 'Abjuration', '{"Clerc","Paladin"}', '1 action', 'Contact', 'V, S', '8 heures', false, false, 'La première fois que la cible devrait tomber à 0 PV, elle reste à 1 PV et le sort prend fin. Annule aussi un effet qui la tuerait instantanément sans infliger de dégâts.'),
  ('Sanctuaire privé de Mordenkainen', 4, 'Abjuration', '{"Magicien"}', '10 minutes', '36 m', 'V, S, M', '24 heures', false, false, 'Protège une zone (cube jusqu''à 30 m) au choix : sons bloqués, opacité, divination impossible, téléportation et voyage planaire bloqués. Plus grand aux niveaux supérieurs ; permanent si lancé un an au même endroit.'),
  ('Sphère résiliente d''Otiluke', 4, 'Évocation', '{"Magicien"}', '1 action', '9 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Jet de Dextérité (si non consentante) ou une sphère de force indestructible enferme une créature ou un objet de taille Grande ou moins. Rien ne la traverse ; l''occupant peut la faire rouler. Désintégration la détruit.'),
  ('Tempête de grêle', 4, 'Évocation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '90 m', 'V, S, M', 'Instantanée', false, false, 'Cylindre de 6 m de rayon : jet de Dextérité, 2d8 contondants + 4d6 froid (moitié si réussi). Le sol devient terrain difficile jusqu''à ton prochain tour. +1d8 contondants par niveau au-delà du 4e.'),
  ('Tentacules noirs d''Evard', 4, 'Invocation', '{"Magicien"}', '1 action', '27 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Un carré de 6 m devient terrain difficile. Toute créature qui y entre ou y commence son tour fait un jet de Dextérité ou subit 3d6 dégâts contondants et est entravée (3d6 de plus à chaque tour).'),
  ('Terrain hallucinatoire', 4, 'Illusion', '{"Barde","Druide","Magicien","Occultiste"}', '10 minutes', '90 m', 'V, S, M', '24 heures', false, false, 'Dans un cube de 45 m, le terrain naturel paraît, sonne et sent comme un autre type de terrain. Les structures et créatures ne sont pas modifiées ; un test d''Intelligence (Investigation) permet de déceler l''illusion.'),
  ('Œil magique', 4, 'Divination', '{"Magicien"}', '1 action', '9 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Un œil invisible flotte et te transmet ce qu''il voit, avec vision dans le noir sur 9 m. Par une action, tu le déplaces de 9 m ; il ne traverse pas les obstacles solides.'),
  ('Animation des objets', 5, 'Transmutation', '{"Barde","Ensorceleur","Magicien"}', '1 action', '36 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Jusqu''à dix petits objets non portés s''animent et t''obéissent ; les objets plus gros comptent pour plusieurs. Une action bonus leur donne des ordres. +2 objets par niveau d''emplacement au-delà du 5e.'),
  ('Apparence trompeuse', 5, 'Illusion', '{"Barde","Ensorceleur","Magicien"}', '1 action', '9 m', 'V, S', '8 heures', false, false, 'Tu modifies l''apparence (corps, vêtements, équipement) d''autant de créatures visibles que tu veux. Une cible non consentante fait un JS de Charisme. Un test d''Intelligence (Investigation) perce l''illusion.'),
  ('Carquois magique', 5, 'Transmutation', '{"Rôdeur"}', '1 action bonus', 'Contact', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Ton carquois fournit des munitions infinies. À chacun de tes tours, tu peux faire deux attaques avec une arme à distance par une action bonus.'),
  ('Cercle de pouvoir', 5, 'Abjuration', '{"Paladin"}', '1 action', 'Personnelle (rayon de 9 m)', 'V', 'Jusqu''à 10 minutes', true, false, 'Toi et tes alliés dans un rayon de 9 m avez l''avantage aux JS contre les sorts et effets magiques. Un JS réussi contre un effet qui inflige la moitié des dégâts n''en inflige aucun.'),
  ('Cercle de téléportation', 5, 'Invocation', '{"Barde","Ensorceleur","Magicien"}', '1 minute', '3 m', 'V, M', '1 round', false, false, 'Tu traces un cercle qui ouvre un portail vers un cercle de téléportation permanent dont tu connais la séquence de symboles, sur le même plan. Tu peux créer un cercle permanent en lançant le sort au même endroit chaque jour pendant un an.'),
  ('Coercition mystique', 5, 'Enchantement', '{"Barde","Clerc","Druide","Magicien","Paladin"}', '1 minute', '18 m', 'V', '30 jours', false, false, 'Une créature qui rate un JS de Sagesse doit accomplir une tâche que tu lui imposes. Chaque jour où elle s''y oppose, elle subit 5d10 dégâts psychiques. Durée prolongée aux emplacements 7 (1 an) et 9 (permanent).'),
  ('Colonne de flamme', 5, 'Évocation', '{"Clerc"}', '1 action', '18 m', 'V, S, M', 'Instantanée', false, false, 'Un cylindre de feu divin de 3 m de rayon et 12 m de haut : JS de Dextérité, 4d6 dégâts de feu + 4d6 dégâts radiants (moitié si réussi). +1d6 (feu ou radiant) par niveau au-delà du 5e.'),
  ('Communion', 5, 'Divination', '{"Clerc"}', '1 minute', 'Personnelle', 'V, S, M', '1 minute', false, true, 'Tu contactes ta divinité ou un intermédiaire et poses jusqu''à trois questions fermées (oui/non). Lancé plusieurs fois avant un repos long, chaque nouvelle tentative risque de rester sans réponse.'),
  ('Communion avec la nature', 5, 'Divination', '{"Druide","Rôdeur"}', '1 minute', 'Personnelle', 'V, S', 'Instantanée', false, true, 'Tu obtiens des connaissances sur le terrain environnant (5 km en extérieur, 90 m sous terre) : jusqu''à trois faits parmi relief, eaux, plantes, animaux, créatures puissantes, influences planaires ou constructions.'),
  ('Contacter un autre plan', 5, 'Divination', '{"Magicien","Occultiste"}', '1 minute', 'Personnelle', 'V', '1 minute', false, true, 'Tu interroges une entité d''un autre plan (jusqu''à cinq questions). JS d''Intelligence DD 15 : en cas d''échec, 6d6 dégâts psychiques et folie jusqu''au prochain repos long.'),
  ('Contagion', 5, 'Nécromancie', '{"Clerc","Druide"}', '1 action', 'Contact', 'V, S', '7 jours', false, false, 'Attaque de sort au corps à corps : la cible est empoisonnée. Après trois JS de Constitution ratés, elle contracte pour 7 jours une maladie de ton choix (aveuglement, mal pourrissant, fièvre, etc.) ; trois réussites la guérissent.'),
  ('Coquille antivie', 5, 'Abjuration', '{"Druide"}', '1 action', 'Personnelle (rayon de 3 m)', 'V, S', 'Jusqu''à 1 heure', true, false, 'Une barrière de 3 m de rayon se déplace avec toi et empêche toutes les créatures sauf les morts-vivants et les créatures artificielles d''y entrer ou d''y passer quoi que ce soit.'),
  ('Création', 5, 'Illusion', '{"Ensorceleur","Magicien"}', '1 minute', '9 m', 'V, S, M', 'Spéciale', false, false, 'Tu crées un objet non vivant de matière végétale ou minérale (cube de 1,50 m max). Sa durée dépend du matériau (de 1 jour pour le bois à 1 minute pour les gemmes). Cube plus grand de 1,50 m par niveau au-delà du 5e.'),
  ('Cône de froid', 5, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', 'Personnelle (cône de 18 m)', 'V, S, M', 'Instantanée', false, false, 'Un souffle glacé dans un cône de 18 m : JS de Constitution, 8d8 dégâts de froid (moitié si réussi). Une créature tuée devient une statue gelée. +1d8 par niveau au-delà du 5e.'),
  ('Dissipation du mal et du bien', 5, 'Abjuration', '{"Clerc","Paladin"}', '1 action', 'Personnelle', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Les célestes, élémentaires, fées, fiélons et morts-vivants ont le désavantage pour t''attaquer. Tu peux mettre fin au sort pour rompre un charme ou une possession par contact, ou pour renvoyer une telle créature sur son plan (JS de Charisme).'),
  ('Dominer un humanoïde', 5, 'Enchantement', '{"Barde","Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Un humanoïde qui rate un JS de Sagesse est charmé et obéit à tes ordres télépathiques ; tu peux contrôler précisément ses actions. Nouveau JS à chaque dégât subi. Durée accrue aux emplacements 6 (10 min), 7 (1 h) et 8 (8 h).'),
  ('Entrave planaire', 5, 'Abjuration', '{"Barde","Clerc","Druide","Magicien"}', '1 heure', '18 m', 'V, S, M', '24 heures', false, false, 'Une créature céleste, élémentaire, féerique ou fiélon qui rate un JS de Charisme doit te servir pendant la durée. Durée accrue aux emplacements 6 (10 jours), 7 (30 jours), 8 (180 jours) et 9 (1 an et 1 jour).'),
  ('Fléau d''insectes', 5, 'Invocation', '{"Clerc","Druide","Ensorceleur"}', '1 action', '90 m', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Une nuée de sauterelles remplit une sphère de 6 m de rayon (terrain difficile, visibilité réduite) : JS de Constitution, 4d10 dégâts perforants (moitié si réussi). +1d10 par niveau au-delà du 5e.'),
  ('Frappe du bannissement', 5, 'Abjuration', '{"Paladin"}', '1 action bonus', 'Personnelle', 'V', 'Jusqu''à 1 minute', true, false, 'Ta prochaine attaque armée qui touche inflige 5d10 dégâts de force supplémentaires. Si la cible tombe à 50 PV ou moins, elle est bannie sur son plan d''origine (ou un demi-plan si elle est native) jusqu''à la fin du sort.'),
  ('Immobiliser un monstre', 5, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '27 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une créature (pas un mort-vivant) qui rate un JS de Sagesse est paralysée ; elle refait le JS à la fin de chacun de ses tours. +1 cible par niveau au-delà du 5e.'),
  ('Invoquer un élémentaire', 5, 'Invocation', '{"Druide","Magicien"}', '1 minute', '27 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Tu invoques un élémentaire de FP 5 maximum, amical, qui obéit à tes ordres. Si ta concentration est rompue, il devient hostile. FP +1 par niveau au-delà du 5e.'),
  ('Invoquer une volée de projectiles', 5, 'Invocation', '{"Rôdeur"}', '1 action', '45 m', 'V, S, M', 'Instantanée', false, false, 'Des projectiles s''abattent dans un cylindre de 12 m de rayon et 6 m de haut : JS de Dextérité, dégâts de l''arme utilisée (8d8 au lieu de son dé, moitié si réussi).'),
  ('Lien télépathique de Rary', 5, 'Divination', '{"Magicien"}', '1 action', '9 m', 'V, S, M', '1 heure', false, true, 'Tu relies télépathiquement jusqu''à huit créatures consentantes, qui peuvent communiquer entre elles quelle que soit leur langue et à n''importe quelle distance sur le même plan.'),
  ('Légende', 5, 'Divination', '{"Barde","Clerc","Magicien"}', '10 minutes', 'Personnelle', 'V, S, M', 'Instantanée', false, false, 'Tu nommes ou décris une personne, un lieu ou un objet important et obtiens un résumé de son histoire et de ses légendes. Plus tu en sais déjà, plus l''information est précise.'),
  ('Main de Bigby', 5, 'Évocation', '{"Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une grande main de force (PV = tes PV max) agit sur ton action bonus : poing (4d8 dégâts de force), pousser, agripper (2d6+mod contondants par tour) ou s''interposer. +2d8 au poing et +2d6 à l''étreinte par niveau au-delà du 5e.'),
  ('Modification de mémoire', 5, 'Enchantement', '{"Barde","Magicien"}', '1 action', '9 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Une créature qui rate un JS de Sagesse est charmée ; tu peux effacer ou modifier ses souvenirs des dernières 24 heures (10 minutes max). Remonte plus loin aux emplacements 6 (7 jours), 7 (30 jours), 8 (1 an) et 9 (tout).'),
  ('Mur de force', 5, 'Évocation', '{"Magicien"}', '1 action', '36 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Un mur invisible de force (dôme, sphère ou dix panneaux de 3 m) bloque physiquement tout ce qui le traverse, y compris sur le plan éthéré. Il est immunisé contre tous les dégâts ; seul désintégration le détruit.'),
  ('Mur de pierre', 5, 'Évocation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Tu crées un mur de pierre (dix panneaux de 3 m x 3 m, 15 cm d''épaisseur). Les créatures prises dedans font un JS de Dextérité pour s''écarter. Après 10 minutes de concentration, il devient permanent.'),
  ('Nuage mortel', 5, 'Invocation', '{"Ensorceleur","Magicien"}', '1 action', '36 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Une sphère de brouillard empoisonné de 6 m de rayon s''éloigne de toi de 3 m par tour : JS de Constitution, 5d8 dégâts de poison (moitié si réussi). +1d8 par niveau au-delà du 5e.'),
  ('Passage par les arbres', 5, 'Invocation', '{"Druide","Rôdeur"}', '1 action', 'Personnelle', 'V, S', 'Jusqu''à 1 minute', true, false, 'Une fois par tour, tu peux entrer dans un arbre vivant et ressortir d''un arbre de même espèce situé à 150 m ou moins, pour 1,50 m de déplacement.'),
  ('Passe-muraille', 5, 'Transmutation', '{"Magicien"}', '1 action', '9 m', 'V, S, M', '1 heure', false, false, 'Un passage de 1,50 m de large, 2,40 m de haut et 6 m de profondeur s''ouvre dans un mur de bois, de plâtre ou de pierre. À la fin du sort, les créatures dedans sont expulsées sans danger.'),
  ('Relever les morts', 5, 'Nécromancie', '{"Barde","Clerc","Paladin"}', '1 heure', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Ramène à la vie une créature morte depuis 10 jours ou moins, avec 1 PV. Elle subit un malus de -4 à ses jets, réduit de 1 à chaque repos long. Ne restaure pas les parties du corps manquantes.'),
  ('Restauration supérieure', 5, 'Abjuration', '{"Barde","Clerc","Druide"}', '1 action', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Tu supprimes un effet affaiblissant : un niveau d''épuisement, un charme, une pétrification, une malédiction, une réduction de caractéristique ou de PV maximum.'),
  ('Réincarnation', 5, 'Transmutation', '{"Druide"}', '1 heure', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Un humanoïde mort depuis 10 jours ou moins revient à la vie dans un nouveau corps dont la race est tirée au hasard sur une table ; il conserve ses souvenirs et ses capacités.'),
  ('Rêve', 5, 'Illusion', '{"Barde","Magicien","Occultiste"}', '1 minute', 'Spéciale', 'V, S, M', '8 heures', false, false, 'Tu entres en contact par le rêve avec une créature connue sur le même plan. Tu peux lui parler ou lui envoyer un cauchemar (JS de Sagesse : pas de repos et 3d6 dégâts psychiques au réveil).'),
  ('Sanctification', 5, 'Évocation', '{"Clerc"}', '24 heures', 'Contact', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Une zone de 18 m de rayon est consacrée : les célestes, élémentaires, fées, fiélons et morts-vivants ne peuvent y entrer, et tu y ajoutes un effet au choix (courage, ténèbres, lumière, protection contre l''énergie, etc.).'),
  ('Scrutation', 5, 'Divination', '{"Barde","Clerc","Druide","Magicien","Occultiste"}', '10 minutes', 'Personnelle', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Tu observes à distance une créature du même plan via un capteur invisible ; elle fait un JS de Sagesse modifié par ta connaissance d''elle. Tu peux aussi viser un lieu que tu connais.'),
  ('Soin des blessures de groupe', 5, 'Évocation', '{"Barde","Clerc","Druide"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'Jusqu''à six créatures dans une sphère de 9 m de rayon récupèrent chacune 3d8 + ton modificateur de caractéristique d''incantation en PV. +1d8 par niveau au-delà du 5e.'),
  ('Tromperie', 5, 'Illusion', '{"Barde","Magicien"}', '1 action', 'Personnelle', 'S', 'Jusqu''à 1 heure', true, false, 'Tu deviens invisible pendant qu''un double illusoire apparaît à ta place. Tu peux déplacer le double, voir et entendre par ses sens. L''invisibilité cesse si tu attaques ou lances un sort.'),
  ('Télékinésie', 5, 'Transmutation', '{"Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Par ton action, tu déplaces une créature (test opposé avec ta caractéristique d''incantation contre sa Force) ou un objet de 500 kg max, jusqu''à 9 m, et tu peux la maintenir entravée.'),
  ('Vague destructrice', 5, 'Évocation', '{"Paladin"}', '1 action', 'Personnelle (rayon de 9 m)', 'V', 'Instantanée', false, false, 'Les créatures de ton choix à 9 m font un JS de Constitution : 5d6 dégâts de tonnerre + 5d6 radiants ou nécrotiques et à terre en cas d''échec (moitié des dégâts sinon).'),
  ('Éveil', 5, 'Transmutation', '{"Barde","Druide"}', '8 heures', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Une bête ou une plante dont l''Intelligence est de 3 ou moins gagne une Intelligence de 10 et parle une langue que tu connais. Elle est charmée par toi pendant 30 jours.'),
  ('Allié planaire', 6, 'Invocation', '{"Clerc"}', '10 minutes', '18 m', 'V, S', 'Instantanée', false, false, 'Tu demandes l''aide d''une entité d''un autre plan, qui envoie un céleste, un élémentaire ou un fiélon. Il accomplit une tâche en échange d''un paiement négocié.'),
  ('Barrière de lames', 6, 'Évocation', '{"Clerc"}', '1 action', '27 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Un mur de lames tourbillonnantes (30 m de long ou anneau de 18 m) procure un abri aux trois quarts et constitue un terrain difficile. Le traverser : JS de Dextérité, 6d10 dégâts tranchants (moitié si réussi).'),
  ('Cercle de mort', 6, 'Nécromancie', '{"Ensorceleur","Magicien","Occultiste"}', '1 action', '45 m', 'V, S, M', 'Instantanée', false, false, 'Une sphère d''énergie négative de 18 m de rayon : JS de Constitution, 8d6 dégâts nécrotiques (moitié si réussi). +2d6 par niveau au-delà du 6e.'),
  ('Chaîne d''éclairs', 6, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', '45 m', 'V, S, M', 'Instantanée', false, false, 'Un éclair frappe une cible puis rebondit sur jusqu''à trois autres à 9 m : JS de Dextérité, 10d8 dégâts de foudre (moitié si réussi). +1 rebond par niveau au-delà du 6e.'),
  ('Contamination', 6, 'Nécromancie', '{"Clerc"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'Une créature fait un JS de Constitution : 14d6 dégâts nécrotiques (moitié si réussi) et son maximum de PV baisse d''autant pendant 1 heure. Ce sort ne peut pas réduire ses PV max sous 1.'),
  ('Contingence', 6, 'Évocation', '{"Magicien"}', '10 minutes', 'Personnelle', 'V, S, M', '10 jours', false, false, 'Tu associes un sort de niveau 5 ou moins (1 action, pouvant te cibler) à une condition déclencheuse : il se lance automatiquement sur toi quand elle se produit. Une seule contingence active à la fois.'),
  ('Convocations instantanées de Drawmij', 6, 'Invocation', '{"Magicien"}', '1 minute', 'Contact', 'V, S, M', 'Jusqu''à dissipation', false, true, 'Tu marques un objet de 5 kg max avec un saphir. En écrasant le saphir par une action, l''objet apparaît instantanément dans ta main, où qu''il soit sur ton plan.'),
  ('Création de mort-vivant', 6, 'Nécromancie', '{"Clerc","Magicien","Occultiste"}', '1 minute', '3 m', 'V, S, M', 'Instantanée', false, false, 'De nuit, tu animes jusqu''à trois cadavres d''humanoïdes en goules, que tu contrôles 24 heures. Plus de créatures et des types plus puissants (blêmes, momies) aux emplacements 7, 8 et 9.'),
  ('Danse irrésistible d''Otto', 6, 'Enchantement', '{"Barde","Magicien"}', '1 action', '9 m', 'V', 'Jusqu''à 1 minute', true, false, 'Une créature se met à danser sans JS initial : elle dépense tout son mouvement, a le désavantage aux jets d''attaque et aux JS de Dextérité, et les autres ont l''avantage contre elle. JS de Sagesse par action pour s''en libérer.'),
  ('Déplacer la terre', 6, 'Transmutation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 2 heures', true, false, 'Toutes les 10 minutes, tu remodèles le terrain (terre, sable, argile) dans une zone de 12 m de côté : creuser, élever, aplanir. Ne peut pas manipuler la pierre naturelle.'),
  ('Désintégration', 6, 'Transmutation', '{"Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S, M', 'Instantanée', false, false, 'Un rayon vert : JS de Dextérité ou 10d6+40 dégâts de force. Une créature réduite à 0 PV est réduite en poussière. Détruit aussi un mur de force ou un objet non magique. +3d6 par niveau au-delà du 6e.'),
  ('Festin des héros', 6, 'Invocation', '{"Clerc","Druide"}', '10 minutes', '9 m', 'V, S, M', 'Instantanée', false, false, 'Un banquet pour 12 convives : après 1 heure de repas, ils sont guéris des maladies et du poison, immunisés contre le poison et la peur, ont l''avantage aux JS de Sagesse et +2d10 PV max pendant 24 heures.'),
  ('Globe d''invulnérabilité', 6, 'Abjuration', '{"Ensorceleur","Magicien"}', '1 action', 'Personnelle (rayon de 3 m)', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une barrière de 3 m de rayon bloque les sorts de niveau 5 ou moins lancés de l''extérieur. +1 niveau de sort bloqué par niveau d''emplacement au-delà du 6e.'),
  ('Guérison', 6, 'Évocation', '{"Clerc","Druide"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'Une créature récupère 70 PV et est guérie de l''aveuglement, de la surdité et des maladies. +10 PV par niveau au-delà du 6e.'),
  ('Illusion programmée', 6, 'Illusion', '{"Barde","Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Tu crées une illusion visuelle et sonore qui se déclenche quand une condition que tu fixes est remplie, joue sa scène pendant 5 minutes, puis se réinitialise.'),
  ('Interdiction', 6, 'Abjuration', '{"Clerc"}', '10 minutes', 'Contact', 'V, S, M', '1 jour', false, true, 'Une zone jusqu''à 3 700 m² empêche la téléportation et les voyages planaires, et inflige 5d10 dégâts radiants ou nécrotiques aux types de créatures choisis qui y entrent ou y commencent leur tour.'),
  ('Invoquer une fée', 6, 'Invocation', '{"Druide","Occultiste"}', '1 minute', '27 m', 'V, S', 'Jusqu''à 1 heure', true, false, 'Tu invoques une fée de FP 6 maximum, ou un esprit féerique à forme de bête, qui t''obéit. Si ta concentration est rompue, elle devient hostile. FP +1 par niveau au-delà du 6e.'),
  ('Marche sur le vent', 6, 'Transmutation', '{"Druide"}', '1 minute', '9 m', 'V, S, M', '8 heures', false, false, 'Toi et jusqu''à dix créatures consentantes prenez une forme gazeuse et volez à 90 m de vitesse. Reprendre forme solide (ou l''inverse) prend 1 minute.'),
  ('Mauvais œil', 6, 'Nécromancie', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Personnelle', 'V, S', 'Jusqu''à 1 minute', true, false, 'Chaque tour, par une action, tu vises une créature à 18 m qui fait un JS de Sagesse ou subit un effet au choix : sommeil, panique (effrayée et fuit) ou nausée (désavantage aux attaques et tests).'),
  ('Mot de retour', 6, 'Invocation', '{"Clerc"}', '1 action', '1,50 m', 'V', 'Instantanée', false, false, 'Toi et jusqu''à cinq créatures consentantes êtes téléportés vers un sanctuaire que tu as préalablement désigné dans un temple de ta divinité.'),
  ('Mur d''épines', 6, 'Invocation', '{"Druide"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Un mur de ronces (18 m de long ou anneau) bloque la vue. Y entrer : JS de Dextérité, 7d8 dégâts perforants (moitié si réussi) ; terrain très difficile. +1d8 par niveau au-delà du 6e.'),
  ('Mur de glace', 6, 'Évocation', '{"Magicien"}', '1 action', '36 m', 'V, S, M', 'Jusqu''à 10 minutes', true, false, 'Un mur ou dôme de glace apparaît ; les créatures prises dedans font un JS de Dextérité, 10d6 dégâts de froid (moitié si réussi). Traverser une section brisée inflige 5d6 dégâts de froid. +2d6/+1d6 par niveau au-delà du 6e.'),
  ('Portail magique', 6, 'Invocation', '{"Ensorceleur","Magicien","Occultiste"}', '1 action', '150 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Tu relies deux points visibles à 150 m par des portails : tout ce qui entre par l''un ressort par l''autre. Une action bonus tourne les portails.'),
  ('Possession', 6, 'Nécromancie', '{"Magicien"}', '1 minute', 'Personnelle', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Ton âme entre dans un réceptacle, d''où tu peux posséder un humanoïde à 30 m (JS de Charisme), dont tu prends le contrôle du corps en gardant tes caractéristiques mentales.'),
  ('Protections et sceaux', 6, 'Abjuration', '{"Barde","Magicien"}', '10 minutes', 'Contact', 'V, S, M', '24 heures', false, false, 'Tu protèges un bâtiment (jusqu''à 230 m²) : couloirs embrumés, portes verrouillées et masquées, escaliers couverts de toiles, et des effets magiques au choix contre les intrus.'),
  ('Pétrification', 6, 'Transmutation', '{"Magicien","Occultiste"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une créature qui rate un JS de Constitution est entravée. Elle refait le JS chaque tour : trois échecs la changent en pierre (pétrifiée), trois réussites la libèrent.'),
  ('Rayon de soleil', 6, 'Évocation', '{"Druide","Ensorceleur","Magicien"}', '1 action', 'Personnelle (ligne de 18 m)', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Un rayon de lumière sur une ligne de 18 m : JS de Constitution, 6d8 dégâts radiants et aveuglé jusqu''à ton prochain tour (moitié et pas aveuglé si réussi). Tu peux recommencer par une action chaque tour.'),
  ('Sphère glacée d''Otiluke', 6, 'Évocation', '{"Magicien"}', '1 action', '90 m', 'V, S, M', 'Instantanée', false, false, 'Un globe explose en une sphère de 18 m de rayon : JS de Constitution, 10d6 dégâts de froid (moitié si réussi). Peut geler l''eau ou être gardé pour être lancé plus tard. +1d6 par niveau au-delà du 6e.'),
  ('Suggestion de groupe', 6, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V, M', '24 heures', false, false, 'Jusqu''à douze créatures qui ratent un JS de Sagesse suivent une suggestion raisonnable que tu formules. Durée accrue aux emplacements 7 (10 jours), 8 (30 jours) et 9 (1 an et 1 jour).'),
  ('Transport végétal', 6, 'Invocation', '{"Druide"}', '1 action', '3 m', 'V, S', '1 round', false, false, 'Tu relies une grande plante proche à une autre plante de taille Grande ou plus, connue, sur le même plan. Toute créature peut passer de l''une à l''autre pendant ce round.'),
  ('Trouver un chemin', 6, 'Divination', '{"Barde","Clerc","Druide"}', '1 minute', 'Personnelle', 'V, S, M', 'Jusqu''à 1 jour', true, false, 'Tu connais le chemin physique le plus court et le plus direct vers un lieu fixe que tu connais, sur le même plan.'),
  ('Vision suprême', 6, 'Divination', '{"Barde","Clerc","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Contact', 'V, S, M', '1 heure', false, false, 'La créature touchée bénéficie de vision véritable sur 36 m : elle voit dans les ténèbres magiques, les créatures invisibles, perce les illusions et voit dans le plan éthéré.'),
  ('Boule de feu à explosion retardée', 7, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', '45 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une bille luisante explose à la fin du sort : JS de Dextérité, 12d6 dégâts de feu (moitié si réussi) dans un rayon de 6 m, +1d6 par tour d''attente. +1d6 par niveau au-delà du 7e.'),
  ('Cage de force', 7, 'Évocation', '{"Barde","Magicien","Occultiste"}', '1 action', '30 m', 'V, S, M', '1 heure', false, false, 'Une prison invisible de force (cage ou boîte) enferme une zone. Les créatures ne peuvent en sortir que par magie et après un JS de Charisme. Ne peut pas être dissipée.'),
  ('Changement de plan', 7, 'Invocation', '{"Clerc","Druide","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Toi et jusqu''à huit créatures voyagez vers un autre plan d''existence. Tu peux aussi bannir une créature touchée (attaque au corps à corps, JS de Charisme) vers un plan au choix.'),
  ('Doigt de mort', 7, 'Nécromancie', '{"Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'JS de Constitution : 7d8+30 dégâts nécrotiques (moitié si réussi). Un humanoïde tué se relève en zombi sous ton contrôle permanent.'),
  ('Embruns prismatiques', 7, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', 'Personnelle (cône de 18 m)', 'V, S', 'Instantanée', false, false, 'Huit rayons colorés dans un cône de 18 m : chaque créature fait un JS de Dextérité et subit au hasard 10d6 dégâts (feu, acide, foudre, poison, froid), pétrification, cécité ou bannissement.'),
  ('Forme éthérée', 7, 'Transmutation', '{"Barde","Clerc","Ensorceleur","Magicien","Occultiste"}', '1 action', 'Personnelle', 'V, S', 'Jusqu''à 8 heures', false, false, 'Tu passes dans le plan éthéré limitrophe, où tu te déplaces en voyant le plan matériel en gris. +3 créatures consentantes par niveau au-delà du 7e.'),
  ('Image projetée', 7, 'Illusion', '{"Barde","Magicien"}', '1 action', '750 km', 'V, S, M', 'Jusqu''à 1 jour', true, false, 'Tu crées un double illusoire de toi en un lieu déjà vu. Tu vois, entends et parles par lui et peux le déplacer. Un contact physique révèle qu''il est illusoire.'),
  ('Inversion de la gravité', 7, 'Transmutation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '30 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Dans un cylindre de 15 m de rayon et 30 m de haut, la gravité s''inverse : tout ce qui n''est pas ancré tombe vers le haut. JS de Dextérité pour s''agripper.'),
  ('Invoquer un céleste', 7, 'Invocation', '{"Clerc"}', '1 minute', '27 m', 'V, S', 'Jusqu''à 1 heure', true, false, 'Tu invoques un céleste de FP 4 maximum, amical, qui obéit à tes ordres. FP 5 avec un emplacement de niveau 9.'),
  ('Manoir somptueux de Mordenkainen', 7, 'Invocation', '{"Barde","Magicien"}', '1 minute', '90 m', 'V, S, M', '24 heures', false, false, 'Tu crées une porte vers une demeure extradimensionnelle meublée de 50 cubes de 3 m, avec 100 serviteurs et un festin pour 100 personnes.'),
  ('Mirage', 7, 'Illusion', '{"Barde","Druide","Magicien"}', '10 minutes', 'Vision', 'V, S', '10 jours', false, false, 'Un terrain de 2,5 km² prend l''apparence, le son et la texture d''un autre terrain, y compris des structures. Seule la vision véritable révèle l''illusion.'),
  ('Parole divine', 7, 'Évocation', '{"Clerc"}', '1 action bonus', '9 m', 'V', 'Instantanée', false, false, 'Les créatures choisies à 9 m qui t''entendent font un JS de Charisme. Selon leurs PV : sourdes (50 ou moins), aveuglées et sourdes (40), étourdies aussi (30) ou tuées (20 ou moins). Bannit aussi les extraplanaires.'),
  ('Régénération', 7, 'Transmutation', '{"Barde","Clerc","Druide"}', '1 minute', 'Contact', 'V, S, M', '1 heure', false, false, 'La cible récupère 4d8+15 PV puis 1 PV par round pendant la durée. Ses membres amputés repoussent en 2 minutes.'),
  ('Résurrection', 7, 'Nécromancie', '{"Barde","Clerc"}', '1 heure', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Ramène à la vie avec tous ses PV une créature morte depuis 100 ans ou moins (pas de vieillesse). Régénère les membres manquants, mais impose un malus de -4 s''amenuisant à chaque repos long.'),
  ('Simulacre', 7, 'Illusion', '{"Magicien"}', '12 heures', 'Contact', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Tu crées un double fait de neige ou de glace d''une bête ou d''un humanoïde, avec la moitié de ses PV. Il t''obéit et ne peut pas progresser ; seul un simulacre peut exister à la fois.'),
  ('Symbole', 7, 'Abjuration', '{"Barde","Clerc","Magicien"}', '1 minute', 'Contact', 'V, S, M', 'Jusqu''à dissipation ou déclenchement', false, false, 'Tu inscris un glyphe qui se déclenche selon une condition : effet au choix sur 18 m (mort 10d10, discorde, peur, désespoir, folie, douleur, sommeil, étourdissement) avec JS approprié.'),
  ('Séquestration', 7, 'Transmutation', '{"Magicien"}', '1 action', 'Contact', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Une créature ou un objet est rendu invisible et indétectable par la divination. Une créature est plongée en animation suspendue. Tu peux fixer une condition qui met fin au sort.'),
  ('Tempête de feu', 7, 'Évocation', '{"Clerc","Druide","Ensorceleur"}', '1 action', '45 m', 'V, S', 'Instantanée', false, false, 'Dix cubes de flammes de 3 m de côté : JS de Dextérité, 7d10 dégâts de feu (moitié si réussi). Tu peux épargner la végétation.'),
  ('Téléportation', 7, 'Invocation', '{"Barde","Ensorceleur","Magicien"}', '1 action', '3 m', 'V', 'Instantanée', false, false, 'Toi et jusqu''à huit créatures (ou un objet) êtes transportés vers une destination sur le même plan. La précision dépend de ta familiarité avec le lieu (risque d''incident).'),
  ('Épée de Mordenkainen', 7, 'Évocation', '{"Barde","Magicien"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Une épée de force plane près de toi : attaque de sort au corps à corps, 3d10 dégâts de force. Une action bonus la déplace de 6 m et la fait attaquer de nouveau.'),
  ('Aura sacrée', 8, 'Abjuration', '{"Clerc"}', '1 action', 'Personnelle', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Les créatures de ton choix à 9 m ont l''avantage à tous les JS et les attaquants sont désavantagés. Un fiélon ou mort-vivant qui les touche au corps à corps est aveuglé (JS de Constitution).'),
  ('Bagou', 8, 'Transmutation', '{"Barde","Occultiste"}', '1 action', 'Personnelle', 'V', '1 heure', false, false, 'Pour tes tests de Charisme, tu peux remplacer le résultat du dé par 15. La magie qui détecte le mensonge te considère toujours comme sincère.'),
  ('Champ antimagie', 8, 'Abjuration', '{"Clerc","Magicien"}', '1 action', 'Personnelle (sphère de 3 m)', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Une sphère de 3 m de rayon centrée sur toi annule toute magie : sorts, objets magiques, créatures invoquées et téléportation n''y fonctionnent pas.'),
  ('Clone', 8, 'Nécromancie', '{"Magicien"}', '1 heure', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Tu fais pousser un double inerte d''une créature vivante dans un récipient scellé. Il mûrit en 120 jours ; à la mort de l''original, son âme y transfère.'),
  ('Contrôle du climat', 8, 'Transmutation', '{"Clerc","Druide","Magicien"}', '10 minutes', 'Personnelle (rayon de 7,5 km)', 'V, S, M', 'Jusqu''à 8 heures', true, false, 'Tu modifies progressivement la météo (précipitations, température, vent) dans un rayon de 7,5 km. Les changements prennent 1d4 × 10 minutes à s''installer.'),
  ('Demi-plan', 8, 'Invocation', '{"Magicien","Occultiste"}', '1 action', '18 m', 'S', '1 heure', false, false, 'Tu crées une porte sur une surface plate menant à une pièce vide extradimensionnelle de 9 m de côté. Tu peux retrouver le même demi-plan en relançant le sort.'),
  ('Dominer un monstre', 8, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V, S', 'Jusqu''à 1 heure', true, false, 'Une créature qui rate un JS de Sagesse est charmée et obéit à tes ordres télépathiques. Nouveau JS à chaque dégât subi. Durée 8 heures avec un emplacement de niveau 9.'),
  ('Esprit faible', 8, 'Enchantement', '{"Barde","Druide","Magicien","Occultiste"}', '1 action', '45 m', 'V, S, M', 'Instantanée', false, false, '4d6 dégâts psychiques ; si la cible rate un JS d''Intelligence, son Intelligence et son Charisme tombent à 1 : plus de sorts ni de communication intelligible. Nouveau JS tous les 30 jours.'),
  ('Esprit impénétrable', 8, 'Abjuration', '{"Barde","Magicien"}', '1 action', 'Contact', 'V, S', '24 heures', false, false, 'Une créature est immunisée contre les dégâts psychiques, la lecture des pensées, la divination et l''état charmé pendant 24 heures.'),
  ('Formes animales', 8, 'Transmutation', '{"Druide"}', '1 action', '9 m', 'V, S', 'Jusqu''à 24 heures', true, false, 'Autant de créatures consentantes que tu veux se transforment en bêtes de FP 4 maximum, de taille Grande ou moins. Tu peux changer leur forme par une action.'),
  ('Labyrinthe', 8, 'Invocation', '{"Magicien"}', '1 action', '18 m', 'V, S', 'Jusqu''à 10 minutes', true, false, 'Tu bannis une créature dans un demi-plan labyrinthique. Elle peut s''en échapper avec un test d''Intelligence DD 20 par action.'),
  ('Mot de pouvoir étourdissant', 8, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V', 'Instantanée', false, false, 'Une créature à 150 PV ou moins est étourdie. Elle refait un JS de Constitution à la fin de chacun de ses tours pour se libérer.'),
  ('Nuage incendiaire', 8, 'Invocation', '{"Ensorceleur","Magicien"}', '1 action', '45 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Un nuage de braises de 6 m de rayon se déplace de 3 m par tour : JS de Dextérité, 10d8 dégâts de feu (moitié si réussi) en y entrant ou en y finissant son tour.'),
  ('Répulsion/attirance', 8, 'Enchantement', '{"Druide","Magicien"}', '1 heure', '18 m', 'V, S, M', '10 jours', false, false, 'Une cible (zone ou objet) repousse ou attire un type de créature que tu désignes. JS de Sagesse pour résister ; effrayée ou attirée sinon.'),
  ('Tremblement de terre', 8, 'Évocation', '{"Clerc","Druide","Ensorceleur"}', '1 action', '150 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Un séisme de 30 m de rayon : JS de Dextérité pour ne pas tomber à terre, la concentration est perturbée, des fissures s''ouvrent et les bâtiments peuvent s''effondrer.'),
  ('Tsunami', 8, 'Invocation', '{"Druide"}', '1 minute', 'Champ de vision', 'V, S', 'Jusqu''à 6 rounds', true, false, 'Un mur d''eau de 90 m de long et 90 m de haut : JS de Force, 6d10 dégâts contondants (moitié si réussi). Il avance de 15 m par tour et perd en puissance.'),
  ('Télépathie', 8, 'Évocation', '{"Magicien"}', '1 action', 'Illimitée', 'V, S, M', '24 heures', false, false, 'Tu crées un lien télépathique avec une créature consentante familière, sur le même plan, pour échanger mots, images et sensations.'),
  ('Éclat du soleil', 8, 'Évocation', '{"Druide","Ensorceleur","Magicien"}', '1 action', '45 m', 'V, S, M', 'Instantanée', false, false, 'Lumière solaire sur 18 m de rayon : JS de Constitution, 12d6 dégâts radiants et aveuglé 1 minute (moitié et pas aveuglé si réussi). Les morts-vivants et vases ont le désavantage.'),
  ('Arrêt du temps', 9, 'Transmutation', '{"Ensorceleur","Magicien"}', '1 action', 'Personnelle', 'V', 'Instantanée', false, false, 'Le temps s''arrête pour tous sauf toi : tu joues 1d4+1 tours d''affilée. Le sort cesse si tu affectes une autre créature ou un objet porté.'),
  ('Changement de forme', 9, 'Transmutation', '{"Druide","Magicien"}', '1 action', 'Personnelle', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Tu prends la forme d''une créature de FP inférieur ou égal à ton niveau, en gardant tes caractéristiques mentales. Tu peux changer de forme par une action.'),
  ('Emprisonnement', 9, 'Abjuration', '{"Magicien","Occultiste"}', '1 minute', '9 m', 'V, S, M', 'Jusqu''à dissipation', false, false, 'Une créature qui rate un JS de Sagesse est emprisonnée magiquement (enterrement, chaînage, prison, minimus ou sommeil). Tu fixes une condition qui la libère.'),
  ('Guérison de groupe', 9, 'Évocation', '{"Clerc"}', '1 action', '18 m', 'V, S', 'Instantanée', false, false, 'Tu répartis jusqu''à 700 PV entre des créatures visibles et les soignes de l''aveuglement, de la surdité et des maladies.'),
  ('Mot de pouvoir guérisseur', 9, 'Évocation', '{"Barde"}', '1 action', 'Contact', 'V, S', 'Instantanée', false, false, 'Une créature récupère tous ses PV et n''est plus charmée, effrayée, paralysée ni étourdie. Elle peut se relever par sa réaction.'),
  ('Mot de pouvoir mortel', 9, 'Enchantement', '{"Barde","Ensorceleur","Magicien","Occultiste"}', '1 action', '18 m', 'V', 'Instantanée', false, false, 'Une créature à 100 PV ou moins meurt instantanément.'),
  ('Mur prismatique', 9, 'Abjuration', '{"Magicien"}', '1 action', '18 m', 'V, S', '10 minutes', false, false, 'Un mur ou une sphère de sept couches colorées. Chaque couche traversée inflige un effet (dégâts de feu, acide, foudre, poison, froid, pétrification, cécité, bannissement) à éviter par JS de Dextérité.'),
  ('Métamorphose suprême', 9, 'Transmutation', '{"Barde","Magicien","Occultiste"}', '1 action', '9 m', 'V, S, M', 'Jusqu''à 1 heure', true, false, 'Une créature (JS de Sagesse) ou un objet devient une autre créature ou un objet. Si tu restes concentré la durée totale, la transformation devient permanente.'),
  ('Nuée de météores', 9, 'Évocation', '{"Ensorceleur","Magicien"}', '1 action', '1,5 km', 'V, S', 'Instantanée', false, false, 'Quatre météores frappent des points visibles : JS de Dextérité, 20d6 dégâts de feu + 20d6 contondants dans un rayon de 12 m (moitié si réussi).'),
  ('Portail', 9, 'Invocation', '{"Clerc","Ensorceleur","Magicien"}', '1 action', '18 m', 'V, S, M', 'Jusqu''à 1 minute', true, false, 'Tu ouvres un portail vers un autre plan. Tu peux aussi nommer une créature précise pour l''attirer à travers le portail.'),
  ('Projection astrale', 9, 'Nécromancie', '{"Clerc","Magicien","Occultiste"}', '1 heure', '3 m', 'V, S, M', 'Spéciale', false, false, 'Toi et jusqu''à huit créatures projetez votre forme astrale dans le plan astral, reliée à votre corps par un cordon d''argent. Couper le cordon tue la créature.'),
  ('Prémonition', 9, 'Divination', '{"Barde","Druide","Magicien","Occultiste"}', '1 minute', 'Contact', 'V, S, M', '8 heures', false, false, 'La créature touchée a l''avantage aux jets d''attaque, tests de caractéristique et JS ; les autres ont le désavantage contre elle. Elle ne peut pas être surprise.'),
  ('Résurrection suprême', 9, 'Nécromancie', '{"Clerc","Druide"}', '1 heure', 'Contact', 'V, S, M', 'Instantanée', false, false, 'Ramène à la vie une créature morte depuis 200 ans ou moins, avec tous ses PV, sans séquelles, même si son corps a été détruit.'),
  ('Souhait', 9, 'Invocation', '{"Ensorceleur","Magicien"}', '1 action', 'Personnelle', 'V', 'Instantanée', false, false, 'Reproduis n''importe quel sort de niveau 8 ou moins sans composantes, ou formule un souhait plus large au risque d''effets imprévus et de perdre la capacité de lancer ce sort.'),
  ('Tempête vengeresse', 9, 'Invocation', '{"Druide"}', '1 action', 'Champ de vision', 'V, S', 'Jusqu''à 1 minute', true, false, 'Un nuage d''orage de 108 m de rayon : JS de Constitution, 2d6 dégâts de tonnerre et sourd, puis chaque tour un effet (pluie acide, éclairs, grêle, tempête glaciale).'),
  ('Étrangeté', 9, 'Illusion', '{"Magicien"}', '1 action', '36 m', 'V, S', 'Jusqu''à 1 minute', true, false, 'Les créatures dans une sphère de 9 m font un JS de Sagesse : effrayées et 4d10 dégâts psychiques par tour jusqu''à ce qu''elles réussissent le JS.')
) as v(name, level, school, classes, casting_time, range, components, duration, concentration, ritual, description)
where not exists (select 1 from public.spells s where s.campaign_id is null and s.name = v.name);
